import{_ as d,l as i,o as e,c as l,v as t,p as s,x as o,d as n,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"TOCTOU","description":"","frontmatter":{"title":"TOCTOU","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/toctou.md","filePath":"cs/toctou.md","lastUpdated":1789023840000}'),p={name:"cs/toctou.md"};function A(h,a,_,B,T,u){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="toctou" tabindex="-1">TOCTOU <a class="header-anchor" href="#toctou" aria-label="Permalink to &quot;TOCTOU&quot;">​</a></h1><div class="epigraph"><p>先检查后使用之间，客体可以换人；权限判断必须落在同一不可分割的引用上，而不是落在可被改写的路径名上。</p><footer>—— 据 Saltzer and Schroeder 对完整中介；Anderson；文件系统 TOCTOU 的经典机制叙述</footer></div><p><a href="/cs/capability-vs-acl">上一课</a>对照了能力与 ACL。本课不重讲混淆代理人。缺口是时间：在 <code>stat</code> 与 <code>open</code> 之间，路径指向的 inode 可以变。这是完整中介失败，不是新的矩阵形状。防御是原子打开、对已打开描述符检查、用能力当稳定引用。缓冲区溢出下一课是另一类内存错误。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>能力课留下「持票即允许」。许多 API 却用路径名两次：一次检查，一次使用。两次解析可以落到不同客体上。缺口是<strong>检查与使用的绑定</strong>。本课只讲机制与防御合同，不给可复现的利用序列。</p><p><span class="marginnote">网络上的同类缝是「先查会话再办事」之间会话被换。对象不同，结构同构：缺少单一引用上的原子判决。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>防御：一次系统调用完成「按意图打开」（目录文件描述符 + 不跟随、或等价的安全打开）；之后只对 fd 做 <code>fstat</code>/<code>fchmod</code>。把路径换成能力或 fd 传递。锁与事务在数据库里解决的是另一对象上的同一句话：判决与更新同一快照。本课不写具体攻击者操作。</p>',8)),(e(),s(E,null,{default:o(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E8%B7%AF%E5%BE%84%E5%90%8D%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20GAP%5B%22%E4%B8%AD%E9%97%B4%E7%8A%B6%E6%80%81%E5%8F%AF%E6%94%B9%22%5D%0A%20%20GAP%20--%3E%20USE%5B%22%E4%BD%BF%E7%94%A8%E6%97%B6%E5%B7%B2%E6%98%AF%E5%8F%A6%E4%B8%80%E5%AE%A2%E4%BD%93%22%5D%0A%20%20FD%5B%22%E6%89%93%E5%BC%80%E5%BE%97%E5%88%B0%E7%A8%B3%E5%AE%9A%20fd%22%5D%20--%3E%20SAME%5B%22%E9%9A%8F%E5%90%8E%E5%8F%AA%E5%AF%B9%E5%90%8C%E4%B8%80%E5%BC%95%E7%94%A8%E5%88%A4%E5%86%B3%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TOCTOU 破坏引用监视器的「每次访问都检查」——检查的不是后来那次访问的客体。能力与 Unix fd 把客体钉成句柄，路径只在获得句柄时解析一次。后课内存破坏是改返回地址，不是换路径。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部竞态类漏洞分类写成清单。越界写如何碰到控制数据，下一课只讲机制直觉与防御，仍无利用配方。</p><p>后课默认：判决必须绑在稳定引用上。内存里的越界是另一边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TOCTOU：检查与使用之间客体被替换。</li><li>防御是原子打开与句柄上的再检查。</li><li>缓冲区溢出直觉下一课。</li><li>出处：Saltzer and Schroeder；Anderson。</li></ul>',7))])}const C=d(p,[["render",A]]);export{m as __pageData,C as default};
